window.MG_LAZY_DATA["data/lazy/resources/c403-82f7e9beebd9f120.json"]={sha256:"82f7e9beebd9f120f2c3b412c8a5cfcdf28d281da805265242ac95c5c8aa058d",value:{"sources":[{"id":"v24-case-c4b0b616549a51b9","url":"https://new.abb.com/innovation/industrial-robots","title":"ABB technologies that changed the world: industrial robots","titleEn":"ABB technologies that changed the world: industrial robots","publisher":"ABB","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"c403","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"c403","related":[{"id":"c404","referenceUrls":["https://global.abb/group/en/technology/did-you-know/yumi-robot"],"title":"ABB YuMi 雙臂協作平台","titleEn":"ABB YuMi dual-arm collaborative platform","why":"用兩課的可觀察驗收條件比較模型邊界：交付扭矩流向圖與靜態負載合格表。；教學馬達連續限值 0.16 N·m 下，2 kg 靜載通過、3 kg 不通過；不能用峰值額定替代連續值。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a torque-flow diagram and static-load acceptance table.; With a teaching continuous limit of 0.16 N·m, 2 kg passes and 3 kg fails; peak ratings cannot replace continuous ratings.","difference":"找出雙臂同步瓶頸，避免把兩臂各自最快誤認為整站最快。","differenceEn":"Identify the synchronization bottleneck rather than optimizing each arm in isolation.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["靜態關節扭矩 τj=mgr，馬達需求 τm=τj/(Nη)。；教學質量 2 kg、力臂 0.25 m、N=50、η=0.80、g=9.81 m/s²。；τj=2×9.81×0.25=4.905 N·m；τm=4.905/(50×0.8)=0.122625 N·m。","獨立備料可平行，交接必須等較慢手臂完成；T=max(TL,TR)+TH。；教學左臂 6 s、右臂 4 s、交接 2 s，兩臂未共享備料治具。；T=6+2=8 s；全串行為 6+4+2=12 s，循環縮短 33.333%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Static joint torque is τj=mgr and motor demand is τm=τj/(Nη).; Teaching values are 2 kg, 0.25 m, N=50, η=0.80 and g=9.81 m/s².; τj=2×9.81×0.25=4.905 N·m; τm=4.905/(50×0.8)=0.122625 N·m.","Independent preparation runs in parallel; handover waits for the slower arm: T=max(TL,TR)+TH.; Teaching times are left 6 s, right 4 s and handover 2 s, with separate preparation fixtures.; T=6+2=8 s; serial execution takes 12 s, so cycle time falls by 33.333%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"c413","referenceUrls":["https://bostondynamics.com/products/stretch/"],"title":"Boston Dynamics Stretch 搬箱系統","titleEn":"Boston Dynamics Stretch box-handling system","why":"用兩課的可觀察驗收條件比較模型邊界：交付扭矩流向圖與靜態負載合格表。；教學馬達連續限值 0.16 N·m 下，2 kg 靜載通過、3 kg 不通過；不能用峰值額定替代連續值。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a torque-flow diagram and static-load acceptance table.; With a teaching continuous limit of 0.16 N·m, 2 kg passes and 3 kg fails; peak ratings cannot replace continuous ratings.","difference":"用靜態吸附力模型比較密封良好與漏氣的紙箱表面。","differenceEn":"Compare sealed and leaking carton surfaces with a static suction-force model.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["靜態關節扭矩 τj=mgr，馬達需求 τm=τj/(Nη)。；教學質量 2 kg、力臂 0.25 m、N=50、η=0.80、g=9.81 m/s²。；τj=2×9.81×0.25=4.905 N·m；τm=4.905/(50×0.8)=0.122625 N·m。","理想吸力 ΔpA，再以效率因子 η 表示教學漏氣損失。；教學 Δp=20000 Pa、A=0.004 m²、η=0.50、紙箱質量 2 kg。；F=20000×0.004×0.50=40 N；2 倍靜重需求為 2×2×9.81=39.24 N。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Static joint torque is τj=mgr and motor demand is τm=τj/(Nη).; Teaching values are 2 kg, 0.25 m, N=50, η=0.80 and g=9.81 m/s².; τj=2×9.81×0.25=4.905 N·m; τm=4.905/(50×0.8)=0.122625 N·m.","Ideal suction is ΔpA, multiplied by a teaching efficiency factor η for leakage.; Teaching values: Δp=20000 Pa, A=0.004 m², η=0.50 and carton mass 2 kg.; F=20000×0.004×0.50=40 N; twice the static weight is 39.24 N.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v24-case-8e055f5930d54cde","url":"https://global.abb/group/en/technology/did-you-know/yumi-robot","title":"YuMi collaborative robot","titleEn":"YuMi collaborative robot","publisher":"ABB","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v24-case-01183c19414e1bee","url":"https://bostondynamics.com/products/stretch/","title":"Stretch mobile warehouse robot","titleEn":"Stretch mobile warehouse robot","publisher":"Boston Dynamics","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
